"""Tracker-context prompt formatting shared by all copilot implementations.

These functions render ``TrackerContext`` data and tracker-event attachments
into the JSON blobs the latest-user-message context templates expect. They are
module-level (not ``BaseCopilot`` statics) so the pydantic-ai v2 copilot can
use them without importing the v1 class tree that is scheduled for removal.
"""

import json
from typing import Any, Dict, List, Optional

from rasa.builder.copilot.models import EventContent
from rasa.builder.shared.tracker_context import TrackerContext


def format_conversation_history(tracker_context: Optional[TrackerContext]) -> str:
    """Format conversation history from TrackerContext."""
    conversation_history: Dict[str, Any] = {
        "conversation_history": [],
    }

    if not tracker_context or not tracker_context.conversation_turns:
        return json.dumps(conversation_history, ensure_ascii=False, indent=2)

    conversation_history["conversation_history"] = (
        tracker_context.formatted_conversation_turns
    )
    return json.dumps(conversation_history, ensure_ascii=False, indent=2)


def format_current_state(tracker_context: Optional[TrackerContext]) -> str:
    """Format current state from TrackerContext for LLM consumption.

    Args:
        tracker_context: The TrackerContext containing current state data.

    Returns:
        A JSON string containing the current state information.
    """
    if not tracker_context or not tracker_context.current_state:
        return json.dumps({}, ensure_ascii=False, indent=2)
    current_state = tracker_context.current_state.model_dump()
    return json.dumps(current_state, ensure_ascii=False, indent=2)


def format_tracker_event_attachments(events: List[EventContent]) -> Optional[str]:
    """Format tracker events as JSON dump to be used in the prompt."""
    # We don't want to display the attachment section in the last user message
    # context prompt if there are no attachments.
    if not events:
        return None
    # If there are attachments, return the formatted JSON dump.
    return json.dumps(
        [event_content.model_dump() for event_content in events],
        ensure_ascii=False,
        indent=2,
    )
